/bin/bash -lc "python - <<'PY'
import io, json, urllib.error
from unittest.mock import patch
import openai_client as c
class Transport:
 def __init__(self, result): self.result=result
 def open(self, req, timeout):
  assert req.full_url == 'https://api.openai.com/v1/responses'
  assert req.get_header('Authorization') == 'Bearer test-key'
  assert json.loads(req.data) == {'model':'test-model','input':'synthetic prompt','store':False}
  assert timeout == 60
  return io.BytesIO(json.dumps(self.result).encode())
response={'status':'completed','output':[{'type':'reasoning'}, {'type':'message','content':[{'type':'output_text','text':'Hello'}, {'type':'output_text','text':' world'}]}]}
with patch.object(c.urllib.request, 'build_opener', return_value=Transport(response)):
 assert c.send_prompt('synthetic prompt',model='test-model',api_key='[REDACTED_SECRET]') == 'Hello world'
for response in [{'status':'incomplete'}, {'status':'completed','output':[{'type':'message','content':[{'type':'refusal'}]}]}, {'status':'completed','output':[]}]:
 with patch.object(c.urllib.request,'build_opener',return_value=Transport(response)):
  try: c.send_prompt('synthetic prompt',model='test-model',api_key='[REDACTED_SECRET]')
  except c.OpenAIError: pass
  else: raise AssertionError('Expected failure')
with patch.object(c.urllib.request.OpenerDirector,'open',side_effect=urllib.error.HTTPError(c._ENDPOINT,429,'private body',{},io.BytesIO(b'private body'))):
 try: c.send_prompt('synthetic prompt',model='test-model',api_key='[REDACTED_SECRET]')
 except c.OpenAIError as exc:
  assert exc.status_code == 429 and 'private body' not in str(exc)
 else: raise AssertionError('Expected HTTP failure')
assert c._NoRedirect().redirect_request(None,None,302,'',{},'https://example.com') is None
print('Passed: request payload, output extraction, incomplete/refusal/empty output, sanitized HTTP errors, redirect blocking.')
PY"

